-- Roles and schemas. Every service has its own role; no service uses a superuser.
-- Passwords are set at deploy time by scripts/apply_role_passwords.sql (generated by
-- `make secrets`), never in migrations.

do $$
declare r text;
begin
  foreach r in array array['charlie_agent','lola_agent','executor_svc','gateway_svc','worker_svc','extractor_svc']
  loop
    if not exists (select 1 from pg_roles where rolname = r) then
      execute format('create role %I nologin noinherit nocreatedb nocreaterole', r);
    end if;
  end loop;
end $$;

create schema if not exists core;
create schema if not exists audit;
create schema if not exists guest;
create schema if not exists lager;

revoke all on schema core, audit, guest, lager from public;
revoke create on schema public from public;

-- Extractor has no database access at all (no usage on any schema).
-- Lola can only use the guest schema.
grant usage on schema guest to lola_agent;
grant usage on schema core, guest, lager to charlie_agent;
grant usage on schema core, audit, guest, lager to executor_svc, worker_svc;
grant usage on schema core, audit to gateway_svc;
grant usage on schema audit to charlie_agent;
